CREATE TABLE social_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),display_name text NOT NULL,bio text NOT NULL DEFAULT '',privacy text NOT NULL DEFAULT 'private' CHECK(privacy IN ('public','private')));
CREATE TABLE social_follows(follower_id uuid REFERENCES users(id),followed_id uuid REFERENCES users(id),status text NOT NULL CHECK(status IN ('pending','accepted')),PRIMARY KEY(follower_id,followed_id),CHECK(follower_id<>followed_id));
CREATE TABLE social_blocks(blocker_id uuid REFERENCES users(id),blocked_id uuid REFERENCES users(id),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('image','video','document')),status text NOT NULL CHECK(status IN ('pending','processing','ready','rejected')),mime text NOT NULL,byte_count integer NOT NULL CHECK(byte_count>0),storage_key text NOT NULL UNIQUE,pet_id uuid REFERENCES pets(id),created_at timestamptz NOT NULL DEFAULT now(),failure text);
CREATE TABLE social_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,visibility text NOT NULL CHECK(visibility IN ('public','followers','private')),kind text NOT NULL CHECK(kind IN ('post','story','reel')),asset_id uuid REFERENCES media_assets(id),expires_at timestamptz,deleted_at timestamptz,moderated_at timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_post_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES social_posts(id),version integer NOT NULL,body text NOT NULL,changed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(post_id,version));
CREATE TABLE social_reactions(post_id uuid REFERENCES social_posts(id),user_id uuid REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('like','save')),PRIMARY KEY(post_id,user_id,kind));
CREATE TABLE social_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES social_posts(id),user_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE direct_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES users(id),recipient_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,UNIQUE(sender_id,idempotency_key),CHECK(sender_id<>recipient_id));
CREATE TABLE abuse_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES users(id),post_id uuid REFERENCES social_posts(id),reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','removed','dismissed')),reviewed_by uuid REFERENCES users(id),review_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE action_limits(actor_id uuid REFERENCES users(id),action text NOT NULL,bucket timestamptz NOT NULL,count integer NOT NULL,PRIMARY KEY(actor_id,action,bucket));
CREATE TABLE adoption_listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),pet_id uuid NOT NULL REFERENCES pets(id),title text NOT NULL,description text NOT NULL,city text NOT NULL,requirements text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','paused','adopted','removed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_adoption ON adoption_listings(pet_id) WHERE status IN ('pending','active','paused');
CREATE TABLE adoption_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES adoption_listings(id),user_id uuid NOT NULL REFERENCES users(id),private_details text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','completed')),reason text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(listing_id,user_id));
CREATE UNIQUE INDEX one_adoption_approval ON adoption_applications(listing_id) WHERE status IN ('approved','completed');
CREATE TABLE rescue_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('rescue','lost','found')),title text NOT NULL,description text NOT NULL,city text NOT NULL,private_location text NOT NULL,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','verified','assigned','in_progress','resolved','rejected')),clinic_id uuid REFERENCES clinics(id),assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE donation_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,purpose text NOT NULL,beneficiary text NOT NULL,goal_minor bigint NOT NULL CHECK(goal_minor>0),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sandbox_donations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES donation_campaigns(id),user_id uuid NOT NULL REFERENCES users(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),idempotency_key uuid NOT NULL,anonymous boolean NOT NULL,status text NOT NULL DEFAULT 'captured' CHECK(status IN ('captured','refunded')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
